.kh-investigation {
  margin: 2.2rem 0;
  padding: clamp(.8rem, 2vw, 1.3rem);
  border: 1px solid #303332;
  border-radius: 5px;
  background: #0b0f10;
  color: #d8dcd9;
}

.kh-investigation header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
}

.kh-investigation h3 {
  font-size: 1.13rem;
  line-height: 1.5;
  margin: 0;
}

.kh-investigation button {
  font: inherit;
  font-size: .9rem;
  min-height: 42px;
  padding: .5rem .75rem;
  background: transparent;
  border: 1px solid #746138;
  border-radius: 3px;
  color: #e7b94a;
  cursor: pointer;
}

.kh-investigation button:disabled {
  opacity: .4;
  cursor: default;
}

.kh-investigation button:focus-visible, .kh-investigation input:focus-visible, .kh-investigation select:focus-visible, .kh-investigation summary:focus-visible, .kh-table-scroll:focus-visible {
  outline: 2px solid #a5c7b5;
  outline-offset: 3px;
}

.kh-predict, .kh-caption, .kh-legend, .kh-note {
  font-size: .92rem;
  line-height: 1.75;
}

.kh-caption, .kh-legend {
  color: #b5bfbb;
}

.kh-controls {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(210px, 1fr));
  gap: 1rem;
  margin: 1.2rem 0;
}

.kh-choice, .kh-range {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: .6rem;
  font-size: .9rem;
}

.kh-range {
  margin: 1.2rem 0;
}

.kh-range > span {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  gap: .7rem;
}

.kh-range output {
  color: #e7b94a;
  font-family: var(--font-mono, monospace);
  flex-shrink: 0;
}

.kh-range input {
  width: 100%;
  min-height: 32px;
  accent-color: #e7b94a;
}

.kh-choice select {
  min-height: 42px;
  width: 100%;
  padding: .5rem;
  border: 1px solid #46504b;
  border-radius: 3px;
  color: #d8dcd9;
  background: #121816;
  font: inherit;
}

.kh-step-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .6rem;
}

.kh-step-controls > span {
  font: .85rem var(--font-mono, monospace);
  color: #bbc4bf;
}

.kh-readout {
  border-left: 2px solid #e7b94a;
  padding-left: .85rem;
  line-height: 1.75;
}

.kh-table-scroll {
  overflow-x: auto;
  scrollbar-gutter: stable;
  max-width: 100%;
  margin: 1.2rem 0;
}

.kh-table-scroll table {
  width: 100%;
  border-collapse: collapse;
  font: .78rem/1.65 var(--font-mono, monospace);
}

.kh-table-scroll caption {
  text-align: left;
  padding: .4rem 0 .8rem;
  color: #bac6bf;
}

.kh-table-scroll th, .kh-table-scroll td {
  padding: .55rem .65rem;
  border-bottom: 1px solid #303a35;
  text-align: left;
  white-space: nowrap;
}

.kh-table-scroll th {
  color: #d0ddd5;
}

.kh-investigation details {
  margin: 1.2rem 0;
}

.kh-investigation summary {
  cursor: pointer;
  color: #e7b94a;
  line-height: 1.7;
}

.kh-scatter, .kh-dendrogram {
  margin: 1.6rem 0;
}

.kh-scatter figcaption, .kh-dendrogram figcaption, .kh-pixel-figure figcaption {
  font-size: .94rem;
  font-weight: 600;
  line-height: 1.6;
  margin-bottom: .6rem;
}

.kh-square-plot {
  position: relative;
  width: 100%;
  max-width: 460px;
  aspect-ratio: 1;
  margin: auto;
}

.kh-square-plot svg, .kh-tree-plot svg {
  width: 100%;
  height: 100%;
  display: block;
  overflow: visible;
}

.kh-point-label, .kh-center-label, .kh-tick, .kh-leaf, .kh-tree-tick {
  position: absolute;
  font: 12px/1.2 var(--font-mono, monospace);
  pointer-events: none;
  white-space: nowrap;
}

.kh-point-label {
  color: #d5ded9;
}

.kh-center-label {
  background: #0b0f10d9;
}

.kh-label-leader {
  stroke: #64766b;
  stroke-width: .75;
  opacity: .7;
}

.kh-label-explanation {
  color: #aebdb4;
  font-size: .78rem;
  line-height: 1.6;
}

.kh-x-tick {
  top: 92%;
  transform: translateX(-50%);
  color: #a5b1aa;
}

.kh-y-tick {
  left: 0;
  transform: translateY(-50%);
  color: #a5b1aa;
}

.kh-axis-caption {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: .4rem 1rem;
  color: #bac6bf;
  font-size: .78rem;
}

.kh-probability-line {
  position: relative;
  display: flex;
  height: 28px;
  margin: 1.8rem 0;
  background: #25332c;
  border-radius: 2px;
}

.kh-probability-line > span {
  display: block;
  min-width: 0;
  border-right: 1px solid #0b0f10;
  box-sizing: border-box;
}

.kh-probability-line > i {
  position: absolute;
  top: -7px;
  bottom: -7px;
  width: 2px;
  background: #f2e7ca;
  box-shadow: 0 0 0 1px #0b0f10;
}

.kh-probability-key {
  display: flex;
  flex-wrap: wrap;
  gap: .55rem .8rem;
  padding: 0;
  margin: 0 0 1.2rem;
  list-style: none;
  font: 12px/1.6 var(--font-mono, monospace);
}

.kh-probability-key li {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: .4rem;
  border: 1px solid transparent;
  padding: .25rem .35rem;
  margin: 0;
}

.kh-probability-key li.is-selected {
  border-color: #8e7c4e;
}

.kh-probability-key strong {
  color: #e7b94a;
  font-weight: 500;
}

.kh-probability-swatch {
  width: 13px;
  height: 13px;
  flex: 0 0 13px;
}

.kh-tree-plot {
  position: relative;
  width: 100%;
  aspect-ratio: 320/256;
}

.kh-leaf {
  top: 89%;
  transform: translateX(-50%);
  text-align: center;
}

.kh-tree-tick {
  left: 0;
  transform: translateY(-50%);
  color: #a5b1aa;
}

.kh-tie-preset {
  margin: .2rem 0 .8rem;
}

.kh-image-pair {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
  margin: 1.5rem 0;
}

.kh-pixel-figure {
  margin: 0;
}

.kh-pixels {
  display: grid;
  outline: 1px solid #536156;
}

.kh-pixels span {
  display: block;
}

.kh-palette {
  display: flex;
  flex-wrap: wrap;
  gap: .7rem 1rem;
}

.kh-palette > div {
  display: grid;
  grid-template-columns: 28px auto;
  gap: .2rem .5rem;
  font-size: .8rem;
}

.kh-palette > div > span {
  width: 28px;
  grid-row: 1/3;
  border: 1px solid #798477;
}

.kh-palette code {
  font-size: .76rem;
  white-space: normal;
}

@media (max-width: 580px) {
  .kh-controls, .kh-image-pair {
    grid-template-columns: 1fr;
  }
  .kh-investigation header {
    gap: .65rem;
  }
  .kh-investigation header button {
    flex-shrink: 0;
  }
}

/* Prediction controls and feedback */
.kh-prediction {
  margin: 1.1rem 0;
  padding: .8rem .9rem;
  border: 1px dashed #4a5650;
  border-radius: 4px;
  font-size: .92rem;
  line-height: 1.7;
}

.kh-prediction > label {
  display: block;
  margin-bottom: .5rem;
}

.kh-prediction-row {
  display: flex;
  flex-wrap: wrap;
  gap: .6rem;
  align-items: stretch;
}

.kh-prediction-row select {
  flex: 1 1 240px;
  min-height: 42px;
  min-width: 0;
  padding: .5rem;
  border: 1px solid #46504b;
  border-radius: 3px;
  color: #d8dcd9;
  background: #121816;
  font: inherit;
}

.kh-prediction-row select:disabled {
  opacity: .6;
}

.kh-feedback {
  margin: .7rem 0 0;
  padding-left: .85rem;
  border-left: 2px solid #8eb9a5;
}

.kh-feedback.is-miss {
  border-left-color: #da9c86;
}

/* Nearest-center boundary */
.kh-boundary {
  stroke: #d9d3bf;
  stroke-width: 1.4;
  stroke-opacity: .75;
}

/* Exhaustive partition and merge tables */
.kh-table-scroll tr.is-best td {
  color: #f0e6c8;
  background: #1a2320;
}

/* Seeding frequency comparison */
.kh-frequency {
  margin: 1.4rem 0;
}

.kh-frequency figcaption {
  font-size: .88rem;
  line-height: 1.6;
  color: #bac6bf;
  margin-bottom: .6rem;
}

.kh-frequency ul {
  list-style: none;
  padding: 0;
  margin: 0;
  display: grid;
  gap: .45rem;
}

.kh-frequency li {
  display: grid;
  grid-template-columns: 2.4rem minmax(0, 1fr) auto;
  gap: .6rem;
  align-items: center;
  margin: 0;
  font: 12px/1.4 var(--font-mono, monospace);
}

.kh-frequency-bars {
  position: relative;
  display: grid;
  gap: 2px;
  min-height: 18px;
}

.kh-frequency-bar {
  display: block;
  height: 8px;
  border-radius: 1px;
  min-width: 0;
}

.kh-frequency-bar.is-observed {
  background: #8a9590;
}

.kh-frequency-uniform {
  position: absolute;
  top: -3px;
  bottom: -3px;
  width: 2px;
  background: #f2e7ca;
  opacity: .8;
}

.kh-frequency-value {
  color: #bbc4bf;
  white-space: nowrap;
}

@media (max-width: 580px) {
  .kh-frequency li {
    grid-template-columns: 2.2rem minmax(0, 1fr);
  }
  .kh-frequency-value {
    grid-column: 2;
  }
}

.cluster-figure { margin: 1.75rem 0; padding: 1.2rem 0; border-block: 1px solid #333; color: #d8d8d8; }
.cluster-figure figcaption { font-size: .94rem; line-height: 1.7; margin-bottom: 1rem; }
.cluster-figure p { font-size: .92rem; line-height: 1.7; }
.cluster-figure svg { display: block; width: 100%; height: auto; overflow: visible; }
.cluster-figure svg text { fill: #d8d8d8; font-size: 13px; font-family: 'Space Grotesk', sans-serif; }
.cluster-figure-pair { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.4rem; }
.cluster-axis { stroke: #666; }
.cluster-connector { stroke: #e2b55a; stroke-width: 1.5; }
.cluster-calculation { font-family: 'JetBrains Mono', monospace; overflow-wrap: anywhere; }
.cluster-linkage-ruler { max-width: 480px; margin-inline: auto; }
.cluster-standalone svg { max-width: 540px; margin-inline: auto; }
.cluster-standalone svg text { font-size: 10.5px; }
.cluster-practice, .cluster-deeper { margin-block: 1.5rem; }
.cluster-practice details, .cluster-deeper { border-left: 2px solid #77623b; padding: .7rem 1rem; }
.cluster-practice summary, .cluster-deeper > summary { color: #e2b55a; cursor: pointer; line-height: 1.6; }
.cluster-practice summary:focus-visible, .cluster-deeper > summary:focus-visible { outline: 2px solid #e2b55a; outline-offset: 5px; }
.cluster-practice details + details { margin-top: .65rem; }
@media (max-width: 600px) {
  .cluster-figure-pair { grid-template-columns: minmax(0, 1fr); gap: .5rem; }
  .cluster-figure { padding-block: 1rem; }
}
@media (max-width: 360px) {
  .cluster-deeper { padding-inline: .65rem; }
}
